import{_ as a,o,c as s,a4 as t}from"./chunks/framework.DA9C4Pbl.js";const u=JSON.parse('{"title":"Arcsecond CLI","description":"","frontmatter":{"title":"Arcsecond CLI","visibility":"public","audience":"developer","tier":"reference","source":"handwritten"},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),n={name:"reference/cli.md"};function i(c,e,r,l,d,h){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="arcsecond-cli" tabindex="-1">Arcsecond CLI <a class="header-anchor" href="#arcsecond-cli" aria-label="Permalink to “Arcsecond CLI”">​</a></h1><p>The Arcsecond CLI is the open-source companion that connects to and interacts with an Arcsecond API server — whether that is the cloud or your own <a href="/concepts/arcsecond-local">Arcsecond.local</a> install. Its main purpose today is precisely this: <strong>to set up and run Arcsecond.local</strong>.</p><p>It is a lightweight command-line tool <em>and</em> a Python module, giving you two entry points:</p><ul><li>the <code>arcsecond</code> command-line tool for day-to-day operations</li><li>the <code>arcsecond</code> Python module for automation and integration</li></ul><p>The CLI works like a tool such as <code>git</code>: <code>arcsecond</code> is the main entry point, followed by a command. Many commands map directly to Arcsecond resources.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arcsecond</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="setting-up-running-arcsecond-local" tabindex="-1">Setting up &amp; running Arcsecond.local <a class="header-anchor" href="#setting-up-running-arcsecond-local" aria-label="Permalink to “Setting up &amp; running Arcsecond.local”">​</a></h2><p>The <code>arcsecond</code> command is how you install, operate and maintain a self-hosted install. The core flow is documented in the <a href="/concepts/arcsecond-local">Arcsecond.local</a> section:</p><ul><li><a href="/start/">Installation</a> — <code>arcsecond setup</code>, then <code>arcsecond start</code>.</li><li><a href="/guides/operating/updates">Updates</a> — <code>arcsecond update</code> moves to the latest release.</li><li>Day to day: <code>arcsecond status</code>, <code>arcsecond logs</code>, <code>arcsecond stop</code>, <code>arcsecond restart</code> — every command and its options is in the <a href="/reference/commands/">command reference</a>, generated from the tool itself.</li><li><a href="/guides/operating/live-image-proxy">Live-Image Proxy</a> — stream USB webcams, all-sky cameras and network cameras into Arcsecond.local.</li><li><a href="/guides/operating/backups">Backups</a> — list, inspect, and restore the Postgres dumps.</li><li><a href="/guides/operating/rotate-postgres-password">Rotate Postgres Password</a> — rotate the database password on an existing install.</li></ul><h2 id="connecting-to-a-server" tabindex="-1">Connecting to a server <a class="header-anchor" href="#connecting-to-a-server" aria-label="Permalink to “Connecting to a server”">​</a></h2><p>The CLI talks to one server at a time — the cloud by default, or your own install once you point it there with <code>arcsecond api use local</code> — and the same commands work against either:</p><ul><li><a href="./cli-login">Install &amp; Login</a> — install the package and authenticate.</li><li><a href="/start/windows-python">Installing on Windows</a> — Windows-specific setup and <code>PATH</code> troubleshooting.</li><li><a href="./upload">Data Upload</a> — upload datasets and all-sky images from the CLI or Python.</li><li><a href="./python-basics">Python API — Basics</a> — reuse your credentials in code (use <code>subdomain=&quot;local&quot;</code> for a self-hosted install).</li><li><a href="./python-resources">Python API — Resources</a> — generic CRUD helpers and target workflows.</li></ul>`,13)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
